PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?answer
WHERE {
  { ?subject ?p ?answerEntity . }
  UNION
  { ?answerEntity ?p ?subject . }
  FILTER(
    ?subject = <http://www.wikidata.org/entity/Q3884> ||
    EXISTS {
      ?subject rdfs:label ?label .
      FILTER(REGEX(STR(?label), "Amazon", "i"))
    }
  )
  FILTER(isIRI(?answerEntity) || isBlank(?answerEntity))
  FILTER(?answerEntity != ?subject)
  ?answerEntity rdfs:label ?answer .
}
ORDER BY ?answer

